//! Stata-layer variance estimators beyond unadjusted/robust/cluster (OLS, IV, GLM).
//!
//! Ground truth, generated by `tests/data/gen_vce_fixtures.do` and `gen_conley_fixtures.R`:
//! - reghdfe 6.13.1 `vce(dkraay [#])` (nlswork panel with gaps, weights, FE nested in time);
//! - ivreghdfe 1.1.4 kernels on OLS (no endogenous regressors: the slope block of fereg's V)
//!   and IV: every kernel, AC/HAC, dkraay(#), Thompson, kiefer, psd0/psda, aw/pw, bw(auto) on a
//!   time series with gaps, tdelta = 2;
//! - Stata 19 `regress y x i.fe, vce(hc2|hc3)` (x block), none/aw/fw, pw (hc2), no FE;
//! - CRV3 do-file jackknife loops of reghdfe / ivreghdfe / ppmlhdfe;
//! - fixest 0.14.2 Conley without small-sample factor (fereg's factor divided out).
//! b and V rtol 1e-8 (V entries below 1e-10*max|V| absolute).

use fereg_core::hac::Kernel;
use fereg_core::{
    AbsorbTerm, AbsorberKind, Bandwidth, ConleyVce, Ctx, EstResult, Family, FactorValues, GlmCollinear, GlmOptions, Guess, IvOptions, KernelVce, Layout, Prep, Psd,
    RfError, Separation, Session, Spec, TimeVars, Vce, WeightKind,
};

const KINDS: &[AbsorberKind] = &[AbsorberKind::Dense, AbsorberKind::Fast];
const RTOL: f64 = 1e-8;

// ---------------------------------------------------------------------------------------------
// Minimal JSON / CSV readers.

#[derive(Clone, Debug)]
enum J {
    Null,
    Num(f64),
    Str(String),
    Arr(Vec<J>),
    Obj(Vec<(String, J)>),
}

impl J {
    fn get(&self, k: &str) -> Option<&J> {
        match self {
            J::Obj(v) => v.iter().find(|(a, _)| a == k).map(|(_, b)| b),
            _ => None,
        }
    }
    fn num(&self) -> f64 {
        match self {
            J::Num(x) => *x,
            J::Null => f64::NAN,
            _ => panic!("not a number: {self:?}"),
        }
    }
    fn nums(&self) -> Vec<f64> {
        match self {
            J::Arr(v) => v.iter().map(J::num).collect(),
            _ => panic!("not an array"),
        }
    }
    fn str(&self) -> &str {
        match self {
            J::Str(s) => s,
            _ => panic!("not a string"),
        }
    }
    fn scalar(&self, k: &str) -> f64 {
        self.get("scalars").and_then(|s| s.get(k)).unwrap_or_else(|| panic!("fixture lacks scalar {k}")).num()
    }
}

fn parse_json(s: &str) -> J {
    fn ws(b: &[u8], i: &mut usize) {
        while *i < b.len() && b[*i].is_ascii_whitespace() {
            *i += 1;
        }
    }
    fn val(b: &[u8], i: &mut usize) -> J {
        ws(b, i);
        match b[*i] {
            b'{' => {
                *i += 1;
                let mut out = Vec::new();
                loop {
                    ws(b, i);
                    if b[*i] == b'}' {
                        *i += 1;
                        return J::Obj(out);
                    }
                    let J::Str(k) = val(b, i) else { panic!("bad key") };
                    ws(b, i);
                    *i += 1;
                    let v = val(b, i);
                    out.push((k, v));
                    ws(b, i);
                    if b[*i] == b',' {
                        *i += 1;
                    }
                }
            }
            b'[' => {
                *i += 1;
                let mut out = Vec::new();
                loop {
                    ws(b, i);
                    if b[*i] == b']' {
                        *i += 1;
                        return J::Arr(out);
                    }
                    out.push(val(b, i));
                    ws(b, i);
                    if b[*i] == b',' {
                        *i += 1;
                    }
                }
            }
            b'"' => {
                *i += 1;
                let st = *i;
                while b[*i] != b'"' {
                    *i += 1;
                }
                *i += 1;
                J::Str(String::from_utf8(b[st..*i - 1].to_vec()).unwrap())
            }
            b'n' => {
                *i += 4;
                J::Null
            }
            _ => {
                let st = *i;
                while *i < b.len() && (b[*i].is_ascii_digit() || b"+-.eE".contains(&b[*i])) {
                    *i += 1;
                }
                J::Num(std::str::from_utf8(&b[st..*i]).unwrap().parse().unwrap())
            }
        }
    }
    let mut i = 0;
    val(s.as_bytes(), &mut i)
}

fn data_dir() -> std::path::PathBuf {
    std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data")
}

fn fixture(name: &str) -> J {
    parse_json(&std::fs::read_to_string(data_dir().join(format!("vce_{name}.json"))).unwrap_or_else(|e| panic!("vce_{name}.json: {e}")))
}

struct Csv {
    names: Vec<String>,
    cols: Vec<Vec<f64>>,
}

impl Csv {
    fn read(name: &str) -> Csv {
        let text = std::fs::read_to_string(data_dir().join(name)).unwrap();
        let mut lines = text.lines();
        let names: Vec<String> = lines.next().unwrap().split(',').map(str::to_string).collect();
        let mut cols = vec![Vec::new(); names.len()];
        for l in lines.filter(|l| !l.is_empty()) {
            for (j, v) in l.split(',').enumerate() {
                cols[j].push(v.parse::<f64>().unwrap());
            }
        }
        Csv { names, cols }
    }
    fn col(&self, n: &str) -> &[f64] {
        &self.cols[self.names.iter().position(|x| x == n).unwrap_or_else(|| panic!("no column {n}"))]
    }
}

// ---------------------------------------------------------------------------------------------
// Running a model.

#[derive(Clone, Copy, Debug, PartialEq)]
enum Est {
    Ols,
    Iv,
    Poisson,
    Logit,
}

struct Model<'a> {
    est: Est,
    /// Factor columns; absorb terms and cluster dims index them.
    factors: Vec<&'a [f64]>,
    absorb: Vec<usize>,
    y: &'a [f64],
    exog: Vec<&'a [f64]>,
    endog: Vec<&'a [f64]>,
    inst: Vec<&'a [f64]>,
    /// Conley coordinates (lat, lon).
    coords: Option<(&'a [f64], &'a [f64])>,
    weights: Option<(&'a [f64], WeightKind)>,
    vce: Vce,
}

fn run(m: &Model, kind: AbsorberKind, threads: usize) -> Result<(Session, EstResult), RfError> {
    let slope_vars: Vec<&[f64]> = m.coords.map(|(a, b)| vec![a, b]).unwrap_or_default();
    let prep = Prep {
        n: m.y.len(),
        factors: m.factors.iter().map(|f| FactorValues::Num(f)).collect(),
        absorb: m.absorb.iter().map(|&f| AbsorbTerm { factors: vec![f], intercept: true, slopes: vec![], save: false }).collect(),
        slope_vars,
        weights: m.weights.map(|w| w.0),
        weight_kind: m.weights.map_or(WeightKind::None, |w| w.1),
        vce: m.vce.clone(),
        drop_singletons: true,
        family: match m.est {
            Est::Poisson => Family::Poisson,
            Est::Logit => Family::Logit,
            Est::Ols | Est::Iv => Family::Gaussian,
        },
        y_for_sep: matches!(m.est, Est::Poisson | Est::Logit).then_some(m.y),
        sep_fe: matches!(m.est, Est::Poisson | Est::Logit),
    };
    let ctx = Ctx::quiet(threads);
    let mut s = Session::prepare_with(prep, &ctx, kind)?;
    let kept: Vec<usize> = s.kept_index().iter().map(|&i| i as usize).collect();
    let pick = |v: &[f64]| -> Vec<f64> { kept.iter().map(|&i| v[i]).collect() };
    let cols: Vec<Vec<f64>> =
        std::iter::once(m.y).chain(m.exog.iter().copied()).chain(m.endog.iter().copied()).chain(m.inst.iter().copied()).map(pick).collect();
    let refs: Vec<&[f64]> = cols.iter().map(Vec::as_slice).collect();
    let rows = s.gather(&refs, &ctx)?;
    let lay = Layout { nx: m.exog.len(), nendog: m.endog.len(), ninst: m.inst.len() };
    let spec = Spec { tol: 1e-14, maxiter: 100_000, iv: IvOptions { first: false, ffirst: false }, ..Spec::default() };
    let res = match m.est {
        Est::Ols => s.ols(rows, &lay, &spec, &ctx)?,
        Est::Iv => s.iv(rows, &lay, &spec, &ctx)?,
        Est::Poisson | Est::Logit => {
            let logit = m.est == Est::Logit;
            let g = GlmOptions {
                family: if logit { Family::Logit } else { Family::Poisson },
                tol: 1e-12,
                maxiter: 10_000,
                itol: 1e-12,
                separation: Separation { relu: !logit, mu: false },
                guess: Guess::Simple,
                log: false,
                collinear: GlmCollinear::Ppmlhdfe,
            };
            s.glm(rows, &lay, None, &spec, &g, &ctx)?
        }
    };
    Ok((s, res))
}

fn rel_err(a: f64, b: f64, atol: f64) -> f64 {
    let d = (a - b).abs();
    if d <= atol { 0.0 } else { d / a.abs().max(b.abs()) }
}

/// Max relative error with an absolute floor of 1e-10*max|want|.
fn vec_err(got: &[f64], want: &[f64]) -> f64 {
    assert_eq!(got.len(), want.len(), "length");
    let scale = want.iter().fold(0.0f64, |m, v| m.max(v.abs()));
    got.iter().zip(want).map(|(a, b)| rel_err(*a, *b, 1e-10 * scale)).fold(0.0, f64::max)
}

/// Max error of a p x p covariance matrix, entry (a, b) relative to sqrt(|V_aa V_bb|) of the
/// fixture (the plain relative error on the diagonal; off-diagonal entries far below the
/// standard errors, e.g. -9e-6 next to variances of 2e-3, are judged on the correlation scale
/// rather than on their own few significant digits).
fn cov_err(got: &[f64], want: &[f64], p: usize) -> f64 {
    assert_eq!(got.len(), want.len(), "length");
    let mut e = 0.0f64;
    for a in 0..p {
        for b in 0..p {
            let s = (want[a * p + a] * want[b * p + b]).abs().sqrt();
            let d = (got[a * p + b] - want[a * p + b]).abs();
            e = e.max(if d == 0.0 { 0.0 } else { d / s.max(want[a * p + b].abs()) });
        }
    }
    e
}

/// Leading p x p block of a k x k row-major matrix.
fn lead(v: &[f64], k: usize, p: usize) -> Vec<f64> {
    (0..p * p).map(|ab| v[(ab / p) * k + ab % p]).collect()
}

fn mat<'a>(res: &'a EstResult, name: &str) -> &'a [f64] {
    &res.matrix(name).unwrap_or_else(|| panic!("missing matrix {name}")).data
}

/// Compares b and V (leading p entries / block of both; `scale` divides fereg's V) with the fixture.
fn check_bv(what: &str, res: &EstResult, j: &J, p: usize, scale: f64, max: &mut (f64, f64)) {
    let b = mat(res, "b");
    let k = b.len();
    let wb = j.get("b").unwrap().nums();
    let wk = wb.len();
    assert!(wk >= p, "{what}: fixture b has {wk} entries, need {p}");
    let wb = wb[..p].to_vec();
    let wv = lead(&j.get("V").unwrap().nums(), wk, p);
    let eb = b[..p].iter().zip(&wb).map(|(a, w)| rel_err(*a, *w, 0.0)).fold(0.0, f64::max);
    let v: Vec<f64> = lead(mat(res, "V"), k, p).iter().map(|x| x / scale).collect();
    let ev = cov_err(&v, &wv, p);
    assert!(eb <= RTOL, "{what}: b rel err {eb:e}\n got {:?}\nwant {wb:?}", &b[..p]);
    assert!(ev <= RTOL, "{what}: V rel err {ev:e}\n got {v:?}\nwant {wv:?}");
    max.0 = max.0.max(eb);
    max.1 = max.1.max(ev);
}

fn scal(res: &EstResult, name: &str) -> f64 {
    res.scalar(name).unwrap_or_else(|| panic!("scalar {name} not produced"))
}

fn assert_scalar(what: &str, res: &EstResult, j: &J, name: &str, ours: &str) {
    let (g, w) = (scal(res, ours), j.scalar(name));
    assert!(rel_err(g, w, 0.0) <= 1e-9, "{what}: {ours} got {g} want {w}");
}

// ---------------------------------------------------------------------------------------------
// reghdfe vce(dkraay)

#[test]
fn dkraay_reghdfe_ground_truth() {
    let d = Csv::read("iv_nls.csv");
    let tv = TimeVars { time: 1, panel: None, delta: 1.0 };
    let specs: &[(&str, &[usize], Option<usize>, Option<(&str, WeightKind)>)] = &[
        ("dk_default", &[0], None, None),
        ("dk_nested", &[0, 1], Some(3), None),
        ("dk_aw", &[0, 1], Some(2), Some(("w", WeightKind::Aweight))),
        ("dk_fw", &[0, 1], Some(2), Some(("fw", WeightKind::Fweight))),
        ("dk_pw", &[0], Some(4), Some(("w", WeightKind::Pweight))),
        ("dk_big", &[0], Some(40), None),
        ("dk_one", &[0], Some(1), None),
    ];
    for &kind in KINDS {
        let mut max = (0.0, 0.0);
        for (name, absorb, bw, wt) in specs {
            let j = fixture(name);
            let m = Model {
                est: Est::Ols,
                factors: vec![d.col("idcode"), d.col("year")],
                absorb: absorb.to_vec(),
                y: d.col("ln_wage"),
                exog: vec![d.col("age"), d.col("tenure")],
                endog: vec![],
                inst: vec![],
                coords: None,
                weights: wt.map(|(c, k)| (d.col(c), k)),
                vce: Vce::Dkraay { time: tv.clone(), bw: *bw },
            };
            let what = format!("{name} [{kind:?}]");
            let (_, res) = run(&m, kind, 3).unwrap_or_else(|e| panic!("{what}: {e}"));
            check_bv(&what, &res, &j, 3, 1.0, &mut max);
            for s in ["N", "df_r", "df_a", "N_clust", "dkraay_bw", "df_m"] {
                assert_scalar(&what, &res, &j, s, s);
            }
            if *name == "dk_big" {
                assert!(res.notes.iter().any(|n| n == "Warning: bandwidth 40 too large for 12 time periods; reducing to 12"), "{what}: {:?}", res.notes);
            }
        }
        eprintln!("[{kind:?}] reghdfe dkraay: max rel err b {:.2e}, V {:.2e}", max.0, max.1);
    }
}

// ---------------------------------------------------------------------------------------------
// ivreghdfe kernels

struct KSpec {
    name: &'static str,
    absorb: &'static [&'static str],
    kernel: Kernel,
    bw: Bandwidth,
    robust: bool,
    cluster: &'static [&'static str],
    kiefer: bool,
    psd: Psd,
    weight: Option<(&'static str, WeightKind)>,
}

fn ks(name: &'static str, absorb: &'static [&'static str], kernel: Kernel, bw: f64, robust: bool) -> KSpec {
    KSpec { name, absorb, kernel, bw: Bandwidth::Fixed(bw), robust, cluster: &[], kiefer: false, psd: Psd::None, weight: None }
}

fn panel_specs() -> Vec<KSpec> {
    use Kernel::*;
    let id: &[&str] = &["idcode"];
    let idyr: &[&str] = &["idcode", "year"];
    let mut v = vec![ks("hac_bartlett", id, Bartlett, 3.0, true), ks("ac_bartlett", idyr, Bartlett, 3.0, false)];
    for (n, k) in [
        ("hac_parzen", Parzen),
        ("hac_truncated", Truncated),
        ("hac_thann", TukeyHanning),
        ("hac_thamm", TukeyHamming),
        ("hac_qs", QuadraticSpectral),
        ("hac_danielle", Daniell),
        ("hac_tent", Tent),
    ] {
        v.push(ks(n, id, k, 3.0, true));
    }
    v.push(ks("ac_parzen_frac", id, Parzen, 2.5, false));
    v.push(KSpec { kiefer: true, ..ks("kiefer", id, Truncated, f64::NAN, false) });
    v.push(KSpec { cluster: &["year"], ..ks("dkraay", id, Bartlett, 3.0, true) });
    v.push(KSpec { cluster: &["year"], ..ks("dkraay_qs", idyr, QuadraticSpectral, 2.0, true) });
    v.push(KSpec { cluster: &["idcode", "year"], ..ks("thompson", &["year"], Bartlett, 2.0, true) });
    v.push(KSpec { cluster: &["year", "idcode"], ..ks("thompson_tru", id, Truncated, 3.0, true) });
    v.push(KSpec { psd: Psd::Abs, ..ks("hac_qs_psda", id, QuadraticSpectral, 4.0, true) });
    v.push(KSpec { psd: Psd::Zero, ..ks("ac_tent_psd0", id, Tent, 4.0, false) });
    v.push(KSpec { weight: Some(("w", WeightKind::Aweight)), ..ks("hac_aw", id, Bartlett, 3.0, true) });
    v.push(KSpec { weight: Some(("w", WeightKind::Pweight)), cluster: &["year"], ..ks("dkraay_pw", idyr, Bartlett, 2.0, true) });
    v.push(KSpec { weight: Some(("w", WeightKind::Aweight)), ..ks("ac_aw", id, Parzen, 3.0, false) });
    v
}

fn ts_specs() -> Vec<KSpec> {
    use Kernel::*;
    let q: &[&str] = &["q"];
    let auto = |name, k| KSpec { bw: Bandwidth::Auto, ..ks(name, q, k, 0.0, true) };
    vec![
        ks("ts_M_hac", q, Bartlett, 4.0, true),
        ks("ts_M_ac_qs", q, QuadraticSpectral, 4.0, false),
        auto("ts_M_auto_bartlett", Bartlett),
        auto("ts_M_auto_parzen", Parzen),
        auto("ts_M_auto_qs", QuadraticSpectral),
        auto("ts_M_auto_tent", Tent),
        KSpec { robust: false, weight: Some(("w", WeightKind::Aweight)), ..auto("ts_M_auto_ac_aw", Bartlett) },
        ks("ts2_M_hac", q, Bartlett, 3.0, true),
        ks("ts2_M_ac_dan", q, Daniell, 5.0, false),
    ]
}

fn kernel_model<'a>(d: &'a Csv, sp: &KSpec, iv: bool, ts: bool, factors: &[&str], tv: TimeVars) -> Model<'a> {
    let fidx = |n: &str| factors.iter().position(|x| *x == n).unwrap();
    let (y, exog, endog, inst): (&str, &[&str], &[&str], &[&str]) = match (ts, iv) {
        (false, false) => ("ln_wage", &["age", "tenure"], &[], &[]),
        (false, true) => ("ln_wage", &["age"], &["tenure"], &["union", "south"]),
        (true, false) => ("y", &["x1", "x2"], &[], &[]),
        (true, true) => ("y", &["x1"], &["en"], &["z1", "z2"]),
    };
    Model {
        est: if iv { Est::Iv } else { Est::Ols },
        factors: factors.iter().map(|f| d.col(f)).collect(),
        absorb: sp.absorb.iter().map(|n| fidx(n)).collect(),
        y: d.col(y),
        exog: exog.iter().map(|n| d.col(n)).collect(),
        endog: endog.iter().map(|n| d.col(n)).collect(),
        inst: inst.iter().map(|n| d.col(n)).collect(),
        coords: None,
        weights: sp.weight.map(|(c, k)| (d.col(c), k)),
        vce: Vce::Kernel(KernelVce {
            kernel: sp.kernel,
            bw: sp.bw,
            robust: sp.robust,
            cluster: sp.cluster.iter().map(|n| vec![fidx(n)]).collect(),
            kiefer: sp.kiefer,
            psd: sp.psd,
            time: tv,
        }),
    }
}

/// One ivreghdfe kernel fixture: b, V (slope block for OLS), and for IV S and the diagnostics.
fn check_kernel(name: &str, m: &Model, kind: AbsorberKind, max: &mut (f64, f64)) {
    let j = fixture(name);
    let what = format!("{name} [{kind:?}]");
    let (_, res) = run(m, kind, 3).unwrap_or_else(|e| panic!("{what}: {e}"));
    let p = j.get("b").unwrap().nums().len();
    check_bv(&what, &res, &j, p, 1.0, max);
    assert_eq!(res.macro_value("kernel"), Some(j.get("kernel").unwrap().str()), "{what}: kernel");
    assert_eq!(res.macro_value("bwchoice").unwrap_or(""), j.get("bwchoice").unwrap().str(), "{what}: bwchoice");
    assert_scalar(&what, &res, &j, "bw", "bw");
    assert_scalar(&what, &res, &j, "df_r", "df_r");
    assert_scalar(&what, &res, &j, "N", "N");
    if j.get("scalars").unwrap().get("N_clust").is_some() {
        assert_scalar(&what, &res, &j, "N_clust", "N_clust");
    }
    if m.est == Est::Iv {
        let s = mat(&res, "S");
        let es = vec_err(s, &j.get("S").unwrap().nums());
        assert!(es <= 1e-8, "{what}: S rel err {es:e}");
        for st in ["j", "idstat", "widstat"] {
            let (g, w) = (scal(&res, st), j.scalar(st));
            assert!(rel_err(g, w, 1e-12) <= 1e-8, "{what}: {st} got {g} want {w}");
        }
        // e(sargan) exactly when ivreghdfe posts it (neither robust nor cluster).
        let want_sargan = j.get("scalars").unwrap().get("sargan").is_some();
        assert_eq!(res.scalar("sargan").is_some(), want_sargan, "{what}: sargan posted");
        if want_sargan {
            assert_scalar(&what, &res, &j, "sargan", "sargan");
        }
    }
}

#[test]
fn ivreghdfe_kernels_ground_truth() {
    let nls = Csv::read("iv_nls.csv");
    let ts = Csv::read("vce_ts.csv");
    for &kind in KINDS {
        let mut max = (0.0, 0.0);
        let mut count = 0;
        for iv in [false, true] {
            let tag = if iv { "iv" } else { "ols" };
            for sp in panel_specs() {
                let m = kernel_model(&nls, &sp, iv, false, &["idcode", "year"], TimeVars { time: 1, panel: Some(0), delta: 1.0 });
                check_kernel(&format!("{tag}_{}", sp.name), &m, kind, &mut max);
                count += 1;
            }
            for sp in ts_specs() {
                let two = sp.name.starts_with("ts2");
                let factors: &[&str] = if two { &["q", "t2"] } else { &["q", "t"] };
                let m = kernel_model(&ts, &sp, iv, true, factors, TimeVars { time: 1, panel: None, delta: if two { 2.0 } else { 1.0 } });
                check_kernel(&sp.name.replace("_M_", &format!("_{tag}_")), &m, kind, &mut max);
                count += 1;
            }
        }
        eprintln!("[{kind:?}] {count} ivreghdfe kernel fixtures: max rel err b {:.2e}, V {:.2e}", max.0, max.1);
    }
}

// ---------------------------------------------------------------------------------------------
// regress vce(hc2|hc3)

#[test]
fn hc2_hc3_regress_ground_truth() {
    let d = Csv::read("vce_cs.csv");
    for &kind in KINDS {
        let mut max = (0.0, 0.0);
        for hc in ["hc2", "hc3"] {
            let vce = if hc == "hc2" { Vce::Hc2 } else { Vce::Hc3 };
            let mut specs: Vec<(String, Option<(&str, WeightKind)>, bool)> = vec![
                (format!("{hc}_none"), None, true),
                (format!("{hc}_aw"), Some(("w", WeightKind::Aweight)), true),
                (format!("{hc}_fw"), Some(("fw", WeightKind::Fweight)), true),
                (format!("{hc}_noabsorb"), None, false),
            ];
            if hc == "hc2" {
                specs.push(("hc2_pw".into(), Some(("w", WeightKind::Pweight)), true));
            }
            for (name, wt, absorb) in specs {
                let j = fixture(&name);
                let m = Model {
                    est: Est::Ols,
                    factors: vec![d.col("f1"), d.col("f2")],
                    absorb: if absorb { vec![0, 1] } else { vec![] },
                    y: d.col("y"),
                    exog: vec![d.col("x1"), d.col("x2")],
                    endog: vec![],
                    inst: vec![],
                    coords: None,
                    weights: wt.map(|(c, k)| (d.col(c), k)),
                    vce: vce.clone(),
                };
                let what = format!("{name} [{kind:?}]");
                let (_, res) = run(&m, kind, 3).unwrap_or_else(|e| panic!("{what}: {e}"));
                let p = if absorb { 2 } else { 3 };
                check_bv(&what, &res, &j, p, 1.0, &mut max);
                assert_scalar(&what, &res, &j, "df_r", "df_r");
                assert_scalar(&what, &res, &j, "N", "N");
            }
        }
        eprintln!("[{kind:?}] regress hc2/hc3: max rel err b {:.2e}, V {:.2e}", max.0, max.1);
    }
}

// ---------------------------------------------------------------------------------------------
// CRV3

#[test]
fn crv3_jackknife_ground_truth() {
    let d = Csv::read("vce_cs.csv");
    let f = |n: &str| ["f1", "f2", "c", "c2"].iter().position(|x| *x == n).unwrap();
    let factors = || vec![d.col("f1"), d.col("f2"), d.col("c"), d.col("c2")];
    let ols = |absorb: &[&str], cl: &[&str], wt: Option<(&str, WeightKind)>| Model {
        est: Est::Ols,
        factors: factors(),
        absorb: absorb.iter().map(|n| f(n)).collect(),
        y: d.col("y"),
        exog: vec![d.col("x1"), d.col("x2")],
        endog: vec![],
        inst: vec![],
        coords: None,
        weights: wt.map(|(c, k)| (d.col(c), k)),
        vce: Vce::Crv3(cl.iter().map(|n| vec![f(n)]).collect()),
    };
    // Single-thread and multi-thread runs must agree bit for bit.
    let mut prev: Option<EstResult> = None;
    for &kind in KINDS {
        let mut max = (0.0, 0.0);
        let cases: Vec<(&str, Model, usize)> = vec![
            ("crv3_ols_nested", ols(&["f1", "f2"], &["c"], None), 3),
            ("crv3_ols_aw", ols(&["f1", "f2"], &["c"], Some(("w", WeightKind::Aweight))), 3),
            ("crv3_ols_c2", ols(&["f2"], &["c2"], None), 3),
            ("crv3_ols_twoway", ols(&["f2"], &["c", "c2"], None), 3),
            (
                "crv3_iv",
                Model {
                    est: Est::Iv,
                    exog: vec![d.col("x1")],
                    endog: vec![d.col("en")],
                    inst: vec![d.col("z1"), d.col("z2")],
                    vce: Vce::Crv3(vec![vec![f("c")]]),
                    ..ols(&["f1", "f2"], &["c"], None)
                },
                2,
            ),
            ("crv3_ppml", Model { est: Est::Poisson, y: d.col("yp"), ..ols(&["f1", "f2"], &["c"], None) }, 2),
        ];
        for (name, m, p) in &cases {
            let j = fixture(name);
            let what = format!("{name} [{kind:?}]");
            let (_, res) = run(m, kind, 4).unwrap_or_else(|e| panic!("{what}: {e}"));
            check_bv(&what, &res, &j, *p, 1.0, &mut max);
            assert_scalar(&what, &res, &j, "N_clust", "N_clust");
            if m.est != Est::Poisson {
                assert_scalar(&what, &res, &j, "df_r", "df_r");
            }
            if *name == "crv3_ols_twoway" && kind == AbsorberKind::Fast {
                let (_, one) = run(m, kind, 1).unwrap();
                if let Some(p) = &prev {
                    assert_eq!(p, &res);
                }
                assert_eq!(one, res, "{what}: results differ between 1 and 4 threads");
                prev = Some(res.clone());
            }
        }
        eprintln!("[{kind:?}] CRV3 jackknife: max rel err b {:.2e}, V {:.2e}", max.0, max.1);
    }
}

// ---------------------------------------------------------------------------------------------
// Conley (fixest)

#[test]
fn conley_fixest_ground_truth() {
    let d = Csv::read("vce_geo.csv");
    let specs: &[(&str, Est, Option<f64>, f64, bool, bool)] = &[
        ("ols_tri", Est::Ols, Some(500.0), 0.0, false, false),
        ("ols_sph", Est::Ols, Some(300.0), 0.0, true, false),
        ("ols_pixel", Est::Ols, Some(500.0), 100.0, false, false),
        ("ols_deduce", Est::Ols, None, 0.0, false, false),
        ("ols_aw", Est::Ols, Some(400.0), 0.0, true, true),
        ("iv_tri", Est::Iv, Some(500.0), 0.0, false, false),
        ("ppml_tri", Est::Poisson, Some(500.0), 0.0, false, false),
        ("logit_sph_pixel", Est::Logit, Some(400.0), 50.0, true, false),
        ("logit_tri", Est::Logit, Some(500.0), 0.0, false, false),
        ("ols_sph_pixel", Est::Ols, Some(400.0), 50.0, true, false),
    ];
    for &kind in KINDS {
        let mut max = (0.0, 0.0);
        for &(name, est, cutoff, pixel, spherical, weighted) in specs {
            let j = fixture(&format!("conley_{name}"));
            let iv = est == Est::Iv;
            let m = Model {
                est,
                factors: vec![d.col("g")],
                absorb: vec![0],
                y: d.col(match est {
                    Est::Poisson => "yp",
                    Est::Logit => "yb",
                    Est::Ols | Est::Iv => "y",
                }),
                exog: if iv { vec![d.col("x1")] } else { vec![d.col("x1"), d.col("x2")] },
                endog: if iv { vec![d.col("en")] } else { vec![] },
                inst: if iv { vec![d.col("z1")] } else { vec![] },
                coords: Some((d.col("lat"), d.col("lon"))),
                weights: weighted.then(|| (d.col("w"), WeightKind::Aweight)),
                vce: Vce::Conley(ConleyVce { lat: 0, lon: 1, cutoff, pixel, spherical }),
            };
            let what = format!("conley_{name} [{kind:?}]");
            let (_, res) = run(&m, kind, 3).unwrap_or_else(|e| panic!("{what}: {e}"));
            let n = scal(&res, "N");
            let factor = match est {
                Est::Ols => n / (n - scal(&res, "df_m") - scal(&res, "df_a")),
                Est::Iv => n / (n - scal(&res, "df_m") - scal(&res, "sdofminus")),
                Est::Poisson | Est::Logit => n / (n - 1.0),
            };
            check_bv(&what, &res, &j, 2, factor, &mut max);
            assert_eq!(scal(&res, "cutoff"), j.get("cutoff").unwrap().num(), "{what}: cutoff");
        }
        eprintln!("[{kind:?}] fixest Conley: max rel err b {:.2e}, V {:.2e}", max.0, max.1);
    }
}

// ---------------------------------------------------------------------------------------------
// Errors, borrowed GLM definitions, thread invariance.

fn nls_ols<'a>(d: &'a Csv, vce: Vce, est: Est, wt: Option<(&'a [f64], WeightKind)>) -> Model<'a> {
    let iv = est == Est::Iv;
    Model {
        est,
        factors: vec![d.col("idcode"), d.col("year")],
        absorb: vec![0],
        y: d.col("ln_wage"),
        exog: if iv { vec![d.col("age")] } else { vec![d.col("age"), d.col("tenure")] },
        endog: if iv { vec![d.col("tenure")] } else { vec![] },
        inst: if iv { vec![d.col("union"), d.col("south")] } else { vec![] },
        coords: None,
        weights: wt,
        vce,
    }
}

#[test]
fn errors_with_reference_texts() {
    let d = Csv::read("iv_nls.csv");
    let tv = TimeVars { time: 1, panel: Some(0), delta: 1.0 };
    let kv = |bw: Bandwidth| KernelVce { kernel: Kernel::Bartlett, bw, robust: true, cluster: vec![], kiefer: false, psd: Psd::None, time: tv.clone() };
    let err = |m: Model| run(&m, AbsorberKind::Fast, 2).err().expect("an error");
    let e = err(nls_ols(&d, Vce::Hc2, Est::Iv, None));
    assert_eq!((e.rc(), e.to_string().contains("vce() only supports cluster, robust, and unadjusted")), (198, true), "{e}");
    let e = err(nls_ols(&d, Vce::Hc3, Est::Ols, Some((d.col("w"), WeightKind::Pweight))));
    assert_eq!(e.rc(), 198, "{e}");
    assert!(e.to_string().contains("pweights not allowed with option vce(hc3)"), "{e}");
    let e = err(nls_ols(&d, Vce::Kernel(kv(Bandwidth::Fixed(2.0))), Est::Ols, Some((d.col("fw"), WeightKind::Fweight))));
    assert_eq!(e.rc(), 101, "{e}");
    // 1970..1988: bw may not exceed (T - 1)/tdelta = 18.
    let e = err(nls_ols(&d, Vce::Kernel(kv(Bandwidth::Fixed(18.5))), Est::Ols, None));
    assert!(e.rc() == 198 && e.to_string().contains("cannot exceed timespan of data"), "{e}");
    assert!(run(&nls_ols(&d, Vce::Kernel(kv(Bandwidth::Fixed(18.0))), Est::Ols, None), AbsorberKind::Fast, 2).is_ok());
    let e = err(nls_ols(&d, Vce::Kernel(kv(Bandwidth::Auto)), Est::Ols, None));
    assert!(e.rc() == 198 && e.to_string().contains("Automatic bandwidth selection not available for panel data"), "{e}");
    let mut bad = kv(Bandwidth::Fixed(2.0));
    bad.cluster = vec![vec![0]];
    let e = err(nls_ols(&d, Vce::Kernel(bad), Est::Ols, None));
    assert!(e.rc() == 198 && e.to_string().contains("requires clustering on tsset time variable"), "{e}");
    // Time series without a panel: duplicate periods.
    let mut dup = kv(Bandwidth::Fixed(2.0));
    dup.time.panel = None;
    let e = err(nls_ols(&d, Vce::Kernel(dup), Est::Ols, None));
    assert_eq!((e.rc(), e.to_string().contains("repeated time values in sample")), (451, true), "{e}");
}

/// Borrowed definitions (no reference): Poisson DK with bw = 1 is the cluster-on-time VCE (both
/// G/(G-1)); every type gives a finite symmetric V, the same for 1 and 6 threads.
#[test]
fn glm_borrowed_and_thread_invariance() {
    let d = Csv::read("vce_geo.csv");
    let n = d.col("y").len();
    let time: Vec<f64> = (0..n).map(|i| (i % 20) as f64 + 1.0).collect();
    let unit: Vec<f64> = (0..n).map(|i| (i / 20) as f64).collect();
    let tv = TimeVars { time: 1, panel: Some(2), delta: 1.0 };
    let pois = |vce: Vce| Model {
        est: Est::Poisson,
        factors: vec![d.col("g"), &time, &unit],
        absorb: vec![0],
        y: d.col("yp"),
        exog: vec![d.col("x1"), d.col("x2")],
        endog: vec![],
        inst: vec![],
        coords: Some((d.col("lat"), d.col("lon"))),
        weights: None,
        vce,
    };
    let (_, dk1) = run(&pois(Vce::Dkraay { time: tv.clone(), bw: Some(1) }), AbsorberKind::Fast, 2).unwrap();
    let (_, cl) = run(&pois(Vce::Cluster(vec![vec![1]])), AbsorberKind::Fast, 2).unwrap();
    let e = vec_err(mat(&dk1, "V"), mat(&cl, "V"));
    assert!(e <= 1e-12, "Poisson DK(bw=1) vs cluster(time): {e:e}");
    let kernel = |robust: bool, cluster: Vec<Vec<usize>>| {
        Vce::Kernel(KernelVce { kernel: Kernel::Bartlett, bw: Bandwidth::Fixed(3.0), robust, cluster, kiefer: false, psd: Psd::None, time: tv.clone() })
    };
    let all = vec![
        Vce::Hc2,
        Vce::Hc3,
        Vce::Crv3(vec![vec![2]]),
        Vce::Dkraay { time: tv.clone(), bw: None },
        kernel(true, vec![]),
        kernel(false, vec![]),
        kernel(true, vec![vec![1]]),
        kernel(true, vec![vec![2], vec![1]]),
        Vce::Conley(ConleyVce { lat: 0, lon: 1, cutoff: Some(300.0), pixel: 0.0, spherical: false }),
    ];
    for vce in all {
        for est in [Est::Poisson, Est::Ols] {
            let m = Model { est, y: d.col(if est == Est::Ols { "y" } else { "yp" }), ..pois(vce.clone()) };
            let (_, a) = run(&m, AbsorberKind::Fast, 1).unwrap_or_else(|e| panic!("{vce:?} {est:?}: {e}"));
            let (_, b) = run(&m, AbsorberKind::Fast, 6).unwrap();
            assert_eq!(a, b, "{vce:?}: results differ between 1 and 6 threads");
            let v = mat(&a, "V");
            let k = mat(&a, "b").len();
            assert!(v.iter().all(|x| x.is_finite()) && (0..k).all(|i| v[i * k + i] > 0.0), "{vce:?}: V {v:?}");
            for i in 0..k {
                for jj in 0..i {
                    assert_eq!(v[i * k + jj], v[jj * k + i], "{vce:?}: V not symmetric");
                }
            }
        }
    }
}
